var n=`0227-feijoada-a-transmontana`;var i=`world-0227`;var a=`PT`;var r=`southern-europe`;var s=4;var o=167;var l={en:`Feijoada à Transmontana`,ua:`Фейжоада по-трансмонтськи`};var d={en:`A traditional Portugal dish made with kidney beans, pork ribs, pork shoulder, chorizo (cured). This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Португалія. Основні інгредієнти: червона квасоля кідні, свинячі ребра, свиняча лопатка, в'ялене чорізо. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var g=[{en:`Cook the listed ingredients in simmering water for about 90 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 90 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:90,i:[[`kidney-beans`,300,`g`],[`water`,1200,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 75 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 75 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:75,i:[[`pork-ribs`,400,`g`],[`pork-shoulder`,350,`g`],[`chorizo-cured`,200,`g`],[`white-cabbage`,300,`g`],[`carrot`,180,`g`],[`yellow-onion`,140,`g`],[`tomato`,200,`g`]]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:2,i:[[`garlic`,3,`clove`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]}];var u={slug:n,id:i,country:`PT`,region:r,servings:4,minutes:167,title:l,text:d,steps:g};export{a as country,u as default,i as id,o as minutes,r as region,s as servings,n as slug,g as steps,d as text,l as title};